// phoneme vector adapter to be used with the LTS model
pub struct pvec {
	l4: u8,
	l3: u8,
	l2: u8,
	l1: u8,
	c: u8,
	r1: u8,
	r2: u8,
	r3: u8,
	r4: u8,
}
impl pvec {
	pub fn new() -> pvec {
		pvec {
			l4: 0,
			l3: 0,
			l2: 0,
			l1: 0,
			c:  0,
			r1: 0,
			r2: 0,
			r3: 0,
			r4: 0,
		}
	}
	pub fn reset(&mut self) {
		self.l4 = 0;
		self.l3 = 0;
		self.l2 = 0;
		self.l1 = 0;
		self.c = 0;
		self.r1 = 0;
		self.r2 = 0;
		self.r3 = 0;
		self.r4 = 0;
	}
	fn letter_to_lts(&mut self, x: u8) -> u8 {
		match x {
			0x27 => {
				// apostrophe
				1
			},
			0x41|0x61 => {
				// A
				2
			},
			0x42|0x62 => {
				// B
				3
			},
			0x43|0x63 => {
				// C
				4
			},
			0x44|0x64 => {
				// D
				5
			},
			0x45|0x65 => {
				// E
				6
			},
			0x46|0x66 => {
				// F
				7
			},
			0x47|0x67 => {
				// G
				8
			},
			0x48|0x68 => {
				// H
				9
			},
			0x49|0x69 => {
				// I
				10
			},
			0x4A|0x6A => {
				// J
				11
			},
			0x4B|0x6B => {
				// K
				12
			},
			0x4C|0x6C => {
				// L
				13
			},
			0x4D|0x6D => {
				// M
				14
			},
			0x4E|0x6E => {
				// N
				15
			},
			0x4F|0x6F => {
				// O
				16
			},
			0x50|0x70 => {
				// P
				17
			},
			0x51|0x71 => {
				// Q
				18
			},
			0x52|0x72 => {
				// R
				19
			},
			0x53|0x73 => {
				// S
				20
			},
			0x54|0x74 => {
				// T
				21
			},
			0x55|0x75 => {
				// U
				22
			},
			0x56|0x76 => {
				// V
				23
			},
			0x57|0x77 => {
				// W
				24
			},
			0x58|0x78 => {
				// X
				25
			},
			0x59|0x79 => {
				// Y
				26
			},
			0x5A|0x7A => {
				// Z
				27
			},
			0x21 => {
				// !
				28
			},
			0x2C => {
				// ,
				29
			},
			0x2E => {
				// .
				30
			},
			0x3F => {
				// ?
				31
			},
			_ => {
				// otherwise
				0
			},
		}
	}
	fn advance(&mut self, x: u8) {
		self.l4 = self.l3;
		self.l3 = self.l2;
		self.l2 = self.l1;
		self.l1 = self.c;
		self.c  = self.r1;
		self.r1 = self.r2;
		self.r2 = self.r3;
		self.r3 = self.r4;
		self.r4 = self.letter_to_lts(x);
	}
	pub fn is_ready(&mut self) -> bool {
		if self.c != 0 { return true; }
		false
	}
	pub fn is_not_last(&mut self) -> bool {
		if self.c != 0 && self.r1 == 0 && self.r2 == 0 && self.r3 == 0 && self.r4 == 0 { return false; }
		true
	}
	pub fn step(&mut self, x: u8) -> (u8, u8, u8, u8, u8, u8, u8, u8, u8) {
		self.advance(x);
		(self.l4, self.l3, self.l2, self.l1, self.c, self.r1, self.r2, self.r3, self.r4)
	}
}

